mapper.update:
UPDATE b_portal_type
SET gmt_modify = now()

    , name = #{name}


    , description = #{description}


    , sort = #{sort}


    , is_delete = #{isDelete}

WHERE id = #{id};

mapper.select:
SELECT id, gmt_create AS gmtCreate, gmt_modify AS gmtModify, name, description, sort, is_delete AS isDelete FROM b_portal_type WHERE 1 = 1
AND is_delete = #{isDelete}
AND name LIKE '%${keyword}%'
ORDER BY sort ASC, id ASC;
